import{_ as e,o,c as r,a as n}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const h=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 5 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 5 из 10","date":"2026-10-07T00:00:00.000Z","source":"https://t.me/jfyi_ps/98","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-07-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-5"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 5 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-07-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-5"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 5 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 5 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-07-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-5\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-07\\"}"]]},"headers":[],"relativePath":"posts/2026-10-07-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-5.md","filePath":"posts/2026-10-07-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-5.md"}'),i={name:"posts/2026-10-07-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-5.md"};function p(a,t,s,l,g,c){return o(),r("div",null,[...t[0]||(t[0]=[n("<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026). ** 5. Кодинг-агент и генерация кода**</p><p>7 базовых инструментов (интерпретатор кода, bash, read/write/edit, glob, grep) покрывают весь универсальный агент. Markdown+Git как центр памяти — аудит, откат. Файл инструкций — дешёвый стабильный префикс.</p><p>Для сложных задач: сначала требования/короткий дизайн-документ на ревью человеку. Завершение = «тесты прошли». Самоконтроль после тестов. Обновляй архитектурную документацию сразу.</p><p>Чёткость цели × автоматизация проверки — максимум эффективности в квадранте «ясно+автоматично». Ограничение в коде сильнее промпта; автоматизируй проверку; быстрая обратная связь → быстрая коррекция; гарантированный откат. Разрушительные хаки (reward hacking) недопустимы даже при прошедших тестах.</p><p><strong>Сбои:</strong> классифицируй по уровню (API/инструмент/контекст/поток управления). Сначала «имеет ли смысл повторять». Детектируй паттерны (отпечаток вызова, счётчик неудач). Watchdog по тишине потока. Эскалация: тихий retry → деградация → показ пользователю только после исчерпания. Ошибки инструмента — в tool-result, не обрыв сессии. Предохранитель с порогом из продакшн-данных; отключай побочные LLM-вызовы на пути ошибки (спираль смерти).</p><p>Практика: потоковое исполнение; параллельность по умолчанию выкл; файлы — диапазоном строк с номерами; состояние среды — в конец контекста; персистентный терминал; linter сразу после записи.</p><p>Поиск: glob → grep → семантика (BM25+эмбеддинги) → AST-символы. Эмбеддинг-индекс кода не обязателен — устаревает, требует поддержки.</p><p>Редактирование: old_string — new_string vs номера строк (путаница в подсчёте) vs diff+apply-модель vs начало+конец блока.</p><p>Безопасность: «смертельное трио» (приватные данные + недоверенный контент + внешняя коммуникация) замыкает атаку; память — усилитель.</p><p><strong>Код как мета-способность:</strong> точные вычисления — LLM формализует, решатель считает. Бизнес-правила — проверка внутри инструмента по данным, независимым от модели. Мультимедиа — Proposer-Reviewer с раздельными контекстами. UI — декларативный протокол из доверенных компонентов, не прямой HTML (риск XSS). SQL — паттерн артефакта: LLM генерирует код, фронтенд выполняет. Самозарождение — копируй проверенную реализацию + точечные правки; авторизацию переноси на уровень данных.</p><p>Продолжение следует...</p>",11)])])}const d=e(i,[["render",p]]);export{h as __pageData,d as default};
